20260514185645	{"DO $$\nDECLARE\n    visit_type_list_id INTEGER;\n    visit_case_list_id INTEGER;\nBEGIN\n    -- Create VISIT_TYPE list if not exists and get its ID\n    INSERT INTO \\"t_list\\" (\\"LIST_ID\\", \\"NAME\\", \\"CREATION_DATE\\", \\"MODIF_USER_ID\\", \\"MODIF_USER_DATE\\", \\"ELIM_USER_ID\\", \\"ELIM_USER_DATE\\", \\"REST_USER_ID\\", \\"REST_USER_DATE\\", \\"STATUS\\")\n    VALUES (500, 'VISIT_TYPE', NOW(), 1, NOW(), 1, NOW(), 1, NOW(), 1)\n    ON CONFLICT (\\"LIST_ID\\") DO NOTHING;\n\n    SELECT \\"LIST_ID\\" INTO visit_type_list_id FROM \\"t_list\\" WHERE UPPER(\\"NAME\\") = 'VISIT_TYPE' LIMIT 1;\n\n    -- Create VISIT_CASE list if not exists and get its ID\n    INSERT INTO \\"t_list\\" (\\"LIST_ID\\", \\"NAME\\", \\"CREATION_DATE\\", \\"MODIF_USER_ID\\", \\"MODIF_USER_DATE\\", \\"ELIM_USER_ID\\", \\"ELIM_USER_DATE\\", \\"REST_USER_ID\\", \\"REST_USER_DATE\\", \\"STATUS\\")\n    VALUES (501, 'VISIT_CASE', NOW(), 1, NOW(), 1, NOW(), 1, NOW(), 1)\n    ON CONFLICT (\\"LIST_ID\\") DO NOTHING;\n\n    SELECT \\"LIST_ID\\" INTO visit_case_list_id FROM \\"t_list\\" WHERE UPPER(\\"NAME\\") = 'VISIT_CASE' LIMIT 1;\n\n    -- Insert VISIT_TYPE values\n    IF visit_type_list_id IS NOT NULL THEN\n        DELETE FROM \\"t_value_list\\" WHERE \\"LIST_ID\\" = visit_type_list_id;\n        INSERT INTO \\"t_value_list\\" (\\"NAME\\", \\"ABBREVIATION\\", \\"LIST_ID\\", \\"CREATION_DATE\\", \\"MODIF_USER_ID\\", \\"MODIF_USER_DATE\\", \\"ELIM_USER_ID\\", \\"ELIM_USER_DATE\\", \\"REST_USER_ID\\", \\"REST_USER_DATE\\", \\"STATUS\\")\n        VALUES\n            ('Presencial', 'PRES', visit_type_list_id, NOW(), 1, NOW(), 1, NOW(), 1, NOW(), 1),\n            ('Virtual', 'VIRT', visit_type_list_id, NOW(), 1, NOW(), 1, NOW(), 1, NOW(), 1),\n            ('Telefónica', 'TEL', visit_type_list_id, NOW(), 1, NOW(), 1, NOW(), 1, NOW(), 1);\n    END IF;\n\n    -- Insert VISIT_CASE values\n    IF visit_case_list_id IS NOT NULL THEN\n        DELETE FROM \\"t_value_list\\" WHERE \\"LIST_ID\\" = visit_case_list_id;\n        INSERT INTO \\"t_value_list\\" (\\"NAME\\", \\"ABBREVIATION\\", \\"LIST_ID\\", \\"CREATION_DATE\\", \\"MODIF_USER_ID\\", \\"MODIF_USER_DATE\\", \\"ELIM_USER_ID\\", \\"ELIM_USER_DATE\\", \\"REST_USER_ID\\", \\"REST_USER_DATE\\", \\"STATUS\\")\n        VALUES\n            ('Visita Inicial', 'VI', visit_case_list_id, NOW(), 1, NOW(), 1, NOW(), 1, NOW(), 1),\n            ('Seguimiento Regular', 'SR', visit_case_list_id, NOW(), 1, NOW(), 1, NOW(), 1, NOW(), 1),\n            ('Revisión de Bitácoras', 'RB', visit_case_list_id, NOW(), 1, NOW(), 1, NOW(), 1, NOW(), 1),\n            ('Evaluación Parcial', 'EP', visit_case_list_id, NOW(), 1, NOW(), 1, NOW(), 1, NOW(), 1),\n            ('Seguimiento a Problemas', 'SP', visit_case_list_id, NOW(), 1, NOW(), 1, NOW(), 1, NOW(), 1),\n            ('Cambio de Empresa', 'CE', visit_case_list_id, NOW(), 1, NOW(), 1, NOW(), 1, NOW(), 1),\n            ('Cambio de Tutor', 'CT', visit_case_list_id, NOW(), 1, NOW(), 1, NOW(), 1, NOW(), 1),\n            ('Suspensión', 'SUS', visit_case_list_id, NOW(), 1, NOW(), 1, NOW(), 1, NOW(), 1),\n            ('Reanudación', 'REA', visit_case_list_id, NOW(), 1, NOW(), 1, NOW(), 1, NOW(), 1),\n            ('Evaluación Final', 'EF', visit_case_list_id, NOW(), 1, NOW(), 1, NOW(), 1, NOW(), 1),\n            ('Certificación', 'CERT', visit_case_list_id, NOW(), 1, NOW(), 1, NOW(), 1, NOW(), 1);\n    END IF;\nEND $$;"}	add_visit_lists	antonysamuel0903@gmail.com	\N	\N
20260519164219	{"-- Tabla de configuración del chat por usuario\nCREATE TABLE IF NOT EXISTS public.t_chat_config (\n    config_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    user_id INTEGER NOT NULL,\n    persona VARCHAR(20) DEFAULT 'formal',\n    quick_actions JSONB DEFAULT '[]',\n    show_notifications BOOLEAN DEFAULT true,\n    created_at TIMESTAMPTZ DEFAULT NOW(),\n    updated_at TIMESTAMPTZ DEFAULT NOW()\n);\n\n-- Índice para búsquedas rápidas por user_id\nCREATE INDEX IF NOT EXISTS idx_chat_config_user_id ON public.t_chat_config(user_id);\n\n-- Un registro por usuario\nCREATE UNIQUE INDEX IF NOT EXISTS idx_chat_config_user_unique ON public.t_chat_config(user_id);"}	create_chat_config_final	antonysamuel0903@gmail.com	\N	\N
20260522162706	{"-- Agregar columna MODULE a t_permissions para agrupar permisos en la UI\nALTER TABLE \\"t_permissions\\" ADD COLUMN IF NOT EXISTS \\"MODULE\\" VARCHAR(50) NOT NULL DEFAULT 'General';\n\n-- Agregar columna IS_SYSTEM a t_roles para proteger roles del sistema\nALTER TABLE \\"t_roles\\" ADD COLUMN IF NOT EXISTS \\"IS_SYSTEM\\" BOOLEAN NOT NULL DEFAULT false;\n\n-- Marcar roles del sistema\nUPDATE \\"t_roles\\" SET \\"IS_SYSTEM\\" = true WHERE \\"ID_ROLS\\" IN (1, 2, 3, 4);\n\n-- Asignar MODULE a permisos existentes basado en el prefijo del NAME\nUPDATE \\"t_permissions\\" SET \\"MODULE\\" = 'Usuarios' WHERE \\"NAME\\" LIKE 'users:%';\nUPDATE \\"t_permissions\\" SET \\"MODULE\\" = 'Estudiantes' WHERE \\"NAME\\" LIKE 'students:%';\nUPDATE \\"t_permissions\\" SET \\"MODULE\\" = 'Tutores' WHERE \\"NAME\\" LIKE 'tutors:%';\nUPDATE \\"t_permissions\\" SET \\"MODULE\\" = 'Instituciones' WHERE \\"NAME\\" LIKE 'institutions:%';\nUPDATE \\"t_permissions\\" SET \\"MODULE\\" = 'Prácticas' WHERE \\"NAME\\" LIKE 'practices:%';\nUPDATE \\"t_permissions\\" SET \\"MODULE\\" = 'Periodos' WHERE \\"NAME\\" LIKE 'periods:%';\nUPDATE \\"t_permissions\\" SET \\"MODULE\\" = 'Respaldos' WHERE \\"NAME\\" LIKE 'backups:%';\nUPDATE \\"t_permissions\\" SET \\"MODULE\\" = 'Reportes' WHERE \\"NAME\\" LIKE 'reports:%';\nUPDATE \\"t_permissions\\" SET \\"MODULE\\" = 'Configuración' WHERE \\"NAME\\" LIKE 'config:%';\nUPDATE \\"t_permissions\\" SET \\"MODULE\\" = 'Carreras' WHERE \\"NAME\\" LIKE 'careers:%';\nUPDATE \\"t_permissions\\" SET \\"MODULE\\" = 'Solicitudes' WHERE \\"NAME\\" LIKE 'requests:%';\n\n-- Asignar permisios al rol ESTUDIANTE (4) si no tiene ninguno\nINSERT INTO \\"t_roles_permissions\\" (\\"ROLES_ID\\", \\"PERMISSIONS_ID\\")\nSELECT 4, \\"PERMISSIONS_ID\\" FROM \\"t_permissions\\"\nWHERE \\"NAME\\" IN ('students:view', 'practices:view', 'reports:view', 'requests:view')\nAND NOT EXISTS (\n  SELECT 1 FROM \\"t_roles_permissions\\" rp\n  WHERE rp.\\"ROLES_ID\\" = 4 AND rp.\\"PERMISSIONS_ID\\" = \\"t_permissions\\".\\"PERMISSIONS_ID\\"\n);"}	add_rbac_columns	antonysamuel0903@gmail.com	\N	\N
