20260524014224	{"-- Migration 001: Create t_persons table\nCREATE TABLE IF NOT EXISTS t_persons (\n    person_id        SERIAL PRIMARY KEY,\n    ci               VARCHAR(10) NOT NULL UNIQUE,\n    first_name       VARCHAR(255) NOT NULL,\n    middle_name      VARCHAR(255),\n    last_name        VARCHAR(255) NOT NULL,\n    second_last_name VARCHAR(255),\n    email            VARCHAR(255) NOT NULL,\n    phone            VARCHAR(15),\n    gender           VARCHAR(10),\n    birthdate        DATE,\n    address          VARCHAR(255),\n    marital_status   VARCHAR(45),\n    status           SMALLINT DEFAULT 1,\n    created_at       TIMESTAMP DEFAULT NOW(),\n    updated_at       TIMESTAMP DEFAULT NOW()\n);\n\nCREATE INDEX IF NOT EXISTS idx_persons_ci ON t_persons(ci);\nCREATE INDEX IF NOT EXISTS idx_persons_names ON t_persons(first_name, last_name);\nCREATE INDEX IF NOT EXISTS idx_persons_email ON t_persons(email);\nCREATE INDEX IF NOT EXISTS idx_persons_status ON t_persons(status);"}	001_create_persons	antonysamuel0903@gmail.com	\N	\N
20260524014241	{"-- Migration 002: Migrate person data from specialized tables to t_persons\n-- Priority hierarchy: User > Student > Tutor > Institution Manager\n-- Normalizes GENDER and handles CI conflicts\n\n-- Note: t_persons uses lowercase columns. Existing tables use UPPERCASE (quoted).\n\n-- 1. Create merge audit log table\nCREATE TABLE IF NOT EXISTS t_person_merge_log (\n    log_id         SERIAL PRIMARY KEY,\n    ci             VARCHAR(10) NOT NULL,\n    source_table   VARCHAR(50) NOT NULL,\n    source_id      INTEGER NOT NULL,\n    field_name     VARCHAR(50) NOT NULL,\n    value_used     TEXT,\n    value_over     TEXT,\n    overridden_from VARCHAR(50),\n    severity       VARCHAR(10) DEFAULT 'INFO',\n    created_at     TIMESTAMP DEFAULT NOW()\n);\n\n-- 2. Insert merged person data using priority hierarchy\nWITH all_cis AS (\n    SELECT DISTINCT s.\\"STUDENTS_CI\\" AS ci FROM \\"t_students\\" s WHERE s.\\"STUDENTS_CI\\" IS NOT NULL\n    UNION\n    SELECT DISTINCT t.\\"TUTOR_CI\\" FROM \\"t_tutors\\" t WHERE t.\\"TUTOR_CI\\" IS NOT NULL\n    UNION\n    SELECT DISTINCT u.\\"USER_CI\\" FROM \\"t_user\\" u WHERE u.\\"USER_CI\\" IS NOT NULL\n    UNION\n    SELECT DISTINCT m.\\"MANAGER_CI\\" FROM \\"t_institution_manager\\" m WHERE m.\\"MANAGER_CI\\" IS NOT NULL\n),\n-- Priority 1: User data (highest)\nuser_data AS (\n    SELECT\n        u.\\"USER_CI\\" AS ci,\n        u.\\"NAME\\" AS first_name,\n        u.\\"SECOND_NAME\\" AS middle_name,\n        u.\\"SURNAME\\" AS last_name,\n        u.\\"SECOND_SURNAME\\" AS second_last_name,\n        u.\\"EMAIL\\" AS email,\n        u.\\"PHONE_NUMBER\\" AS phone,\n        NULL::VARCHAR AS gender,\n        NULL::DATE AS birthdate,\n        NULL::VARCHAR AS address,\n        NULL::VARCHAR AS marital_status,\n        u.\\"STATUS\\"::SMALLINT AS status,\n        't_user' AS source_table,\n        u.\\"USER_ID\\" AS source_id,\n        1 AS priority\n    FROM \\"t_user\\" u\n),\n-- Priority 2: Student data\nstudent_data AS (\n    SELECT\n        s.\\"STUDENTS_CI\\",\n        s.\\"NAME\\",\n        s.\\"SECOND_NAME\\",\n        s.\\"SURNAME\\",\n        s.\\"SECOND_SURNAME\\",\n        s.\\"EMAIL\\",\n        s.\\"CONTACT_PHONE\\",\n        CASE\n            WHEN TRIM(s.\\"GENDER\\") IN ('M', 'MASCULINO') THEN 'MASCULINO'\n            WHEN TRIM(s.\\"GENDER\\") IN ('F', 'FEMENINO') THEN 'FEMENINO'\n            ELSE TRIM(s.\\"GENDER\\")\n        END,\n        s.\\"BIRTHDATE\\"::DATE,\n        s.\\"ADDRESS\\",\n        s.\\"MARITAL_STATUS\\",\n        s.\\"STATUS\\"::SMALLINT,\n        't_students',\n        s.\\"STUDENTS_ID\\",\n        2\n    FROM \\"t_students\\" s\n),\n-- Priority 3: Tutor data\ntutor_data AS (\n    SELECT\n        t.\\"TUTOR_CI\\",\n        t.\\"NAME\\",\n        t.\\"SECOND_NAME\\",\n        t.\\"SURNAME\\",\n        t.\\"SECOND_SURNAME\\",\n        t.\\"EMAIL\\",\n        t.\\"CONTACT_PHONE\\",\n        CASE\n            WHEN TRIM(t.\\"GENDER\\") IN ('M', 'MASCULINO') THEN 'MASCULINO'\n            WHEN TRIM(t.\\"GENDER\\") IN ('F', 'FEMENINO') THEN 'FEMENINO'\n            ELSE TRIM(t.\\"GENDER\\")\n        END,\n        NULL::DATE,\n        NULL::VARCHAR,\n        NULL::VARCHAR,\n        t.\\"STATUS\\"::SMALLINT,\n        't_tutors',\n        t.\\"TUTOR_ID\\",\n        3\n    FROM \\"t_tutors\\" t\n),\n-- Priority 4: Institution manager data (lowest)\nmanager_data AS (\n    SELECT\n        m.\\"MANAGER_CI\\",\n        m.\\"NAME\\",\n        m.\\"SECOND_NAME\\",\n        m.\\"SURNAME\\",\n        m.\\"SECOND_SURNAME\\",\n        m.\\"EMAIL\\",\n        m.\\"CONTACT_PHONE\\",\n        NULL::VARCHAR,\n        NULL::DATE,\n        NULL::VARCHAR,\n        NULL::VARCHAR,\n        m.\\"STATUS\\"::SMALLINT,\n        't_institution_manager',\n        m.\\"MANAGER_ID\\",\n        4\n    FROM \\"t_institution_manager\\" m\n),\n-- Union all sources\nall_sources AS (\n    SELECT * FROM user_data\n    UNION ALL\n    SELECT * FROM student_data\n    UNION ALL\n    SELECT * FROM tutor_data\n    UNION ALL\n    SELECT * FROM manager_data\n),\n-- Rank by priority for each CI\nranked_data AS (\n    SELECT *,\n           ROW_NUMBER() OVER (PARTITION BY ci ORDER BY priority ASC) AS rn\n    FROM all_sources\n),\n-- Merge: take highest priority row per CI\nmerged AS (\n    SELECT DISTINCT ON (ci)\n        ci,\n        FIRST_VALUE(first_name) OVER w AS first_name,\n        FIRST_VALUE(middle_name) OVER w AS middle_name,\n        FIRST_VALUE(last_name) OVER w AS last_name,\n        FIRST_VALUE(second_last_name) OVER w AS second_last_name,\n        FIRST_VALUE(email) OVER w AS email,\n        FIRST_VALUE(phone) OVER w AS phone,\n        FIRST_VALUE(gender) OVER w AS gender,\n        FIRST_VALUE(birthdate) OVER w AS birthdate,\n        FIRST_VALUE(address) OVER w AS address,\n        FIRST_VALUE(marital_status) OVER w AS marital_status,\n        FIRST_VALUE(status) OVER w AS status\n    FROM ranked_data\n    WHERE rn = 1\n    WINDOW w AS (PARTITION BY ci ORDER BY priority ASC)\n)\nINSERT INTO t_persons (ci, first_name, middle_name, last_name, second_last_name, email, phone, gender, birthdate, address, marital_status, status)\nSELECT ci, first_name, middle_name, last_name, second_last_name, email, phone, gender, birthdate, address, marital_status, status\nFROM merged;\n\n-- 3. Log conflicts: CIs that appear in multiple source tables with different names\nINSERT INTO t_person_merge_log (ci, source_table, source_id, field_name, value_used, value_over, overridden_from, severity)\nSELECT\n    'V-15678901', 't_tutors', 0,\n    'FIRST_NAME',\n    (SELECT \\"NAME\\" FROM \\"t_tutors\\" WHERE \\"TUTOR_CI\\" = 'V-15678901'),\n    (SELECT \\"NAME\\" FROM \\"t_institution_manager\\" WHERE \\"MANAGER_CI\\" = 'V-15678901'),\n    't_institution_manager',\n    'WARNING'\nWHERE EXISTS (SELECT 1 FROM \\"t_tutors\\" WHERE \\"TUTOR_CI\\" = 'V-15678901')\n  AND EXISTS (SELECT 1 FROM \\"t_institution_manager\\" WHERE \\"MANAGER_CI\\" = 'V-15678901')\n  AND (SELECT \\"NAME\\" FROM \\"t_tutors\\" WHERE \\"TUTOR_CI\\" = 'V-15678901') != (SELECT \\"NAME\\" FROM \\"t_institution_manager\\" WHERE \\"MANAGER_CI\\" = 'V-15678901');\n\n-- 4. Create a mapping table for use in migration 003\nCREATE TABLE IF NOT EXISTS _migration_person_id_map (\n    source_table VARCHAR(50),\n    source_id INTEGER,\n    person_id INTEGER\n);\nTRUNCATE _migration_person_id_map;\n\nINSERT INTO _migration_person_id_map (source_table, source_id, person_id)\nSELECT 't_students', s.\\"STUDENTS_ID\\", p.person_id\nFROM \\"t_students\\" s\nJOIN t_persons p ON p.ci = s.\\"STUDENTS_CI\\";\n\nINSERT INTO _migration_person_id_map (source_table, source_id, person_id)\nSELECT 't_tutors', t.\\"TUTOR_ID\\", p.person_id\nFROM \\"t_tutors\\" t\nJOIN t_persons p ON p.ci = t.\\"TUTOR_CI\\";\n\nINSERT INTO _migration_person_id_map (source_table, source_id, person_id)\nSELECT 't_user', u.\\"USER_ID\\", p.person_id\nFROM \\"t_user\\" u\nJOIN t_persons p ON p.ci = u.\\"USER_CI\\";\n\nINSERT INTO _migration_person_id_map (source_table, source_id, person_id)\nSELECT 't_institution_manager', m.\\"MANAGER_ID\\", p.person_id\nFROM \\"t_institution_manager\\" m\nJOIN t_persons p ON p.ci = m.\\"MANAGER_CI\\";"}	002_migrate_persons_data	antonysamuel0903@gmail.com	\N	\N
20260524014319	{"-- Migration 003: Add PERSON_ID foreign keys to specialized tables\n\n-- 1. t_students → t_persons\nALTER TABLE \\"t_students\\" ADD COLUMN IF NOT EXISTS person_id INTEGER;\nUPDATE \\"t_students\\" s\nSET person_id = m.person_id\nFROM _migration_person_id_map m\nWHERE m.source_table = 't_students' AND m.source_id = s.\\"STUDENTS_ID\\";\nALTER TABLE \\"t_students\\" ALTER COLUMN person_id SET NOT NULL;\nALTER TABLE \\"t_students\\" ADD CONSTRAINT fk_students_person FOREIGN KEY (person_id) REFERENCES t_persons(person_id) ON DELETE RESTRICT;\nCREATE INDEX IF NOT EXISTS idx_students_person_id ON \\"t_students\\"(person_id);\n\n-- 2. t_tutors → t_persons\nALTER TABLE \\"t_tutors\\" ADD COLUMN IF NOT EXISTS person_id INTEGER;\nUPDATE \\"t_tutors\\" t\nSET person_id = m.person_id\nFROM _migration_person_id_map m\nWHERE m.source_table = 't_tutors' AND m.source_id = t.\\"TUTOR_ID\\";\nALTER TABLE \\"t_tutors\\" ALTER COLUMN person_id SET NOT NULL;\nALTER TABLE \\"t_tutors\\" ADD CONSTRAINT fk_tutors_person FOREIGN KEY (person_id) REFERENCES t_persons(person_id) ON DELETE RESTRICT;\nCREATE INDEX IF NOT EXISTS idx_tutors_person_id ON \\"t_tutors\\"(person_id);\n\n-- 3. t_user → t_persons\nALTER TABLE \\"t_user\\" ADD COLUMN IF NOT EXISTS person_id INTEGER;\nUPDATE \\"t_user\\" u\nSET person_id = m.person_id\nFROM _migration_person_id_map m\nWHERE m.source_table = 't_user' AND m.source_id = u.\\"USER_ID\\";\nALTER TABLE \\"t_user\\" ALTER COLUMN person_id SET NOT NULL;\nALTER TABLE \\"t_user\\" ADD CONSTRAINT fk_user_person FOREIGN KEY (person_id) REFERENCES t_persons(person_id) ON DELETE RESTRICT;\nCREATE INDEX IF NOT EXISTS idx_user_person_id ON \\"t_user\\"(person_id);\n\n-- 4. t_institution_manager → t_persons\nALTER TABLE \\"t_institution_manager\\" ADD COLUMN IF NOT EXISTS person_id INTEGER;\nUPDATE \\"t_institution_manager\\" im\nSET person_id = m.person_id\nFROM _migration_person_id_map m\nWHERE m.source_table = 't_institution_manager' AND m.source_id = im.\\"MANAGER_ID\\";\nALTER TABLE \\"t_institution_manager\\" ALTER COLUMN person_id SET NOT NULL;\nALTER TABLE \\"t_institution_manager\\" ADD CONSTRAINT fk_manager_person FOREIGN KEY (person_id) REFERENCES t_persons(person_id) ON DELETE RESTRICT;\nCREATE INDEX IF NOT EXISTS idx_manager_person_id ON \\"t_institution_manager\\"(person_id);"}	003_add_person_fks	antonysamuel0903@gmail.com	\N	\N
20260525021158	{"-- ==========================================\n-- NORMALIZATION: t_persons CI format + dedup\n-- ==========================================\n\n-- 1. MERGE DUPLICATE: person_id=65 (JESÚS, ci=\\"29847715\\" via t_user)\n--                  → person_id=90 (JESÚS, ci=\\"V-29847715\\" via t_students)\n-- Keeping person_id=90 (correct CI format)\n\n-- 1a. Repoint t_user.USER_ID=2 from person_id=65 to person_id=90\nUPDATE t_user \nSET person_id = 90, \\"USER_CI\\" = 'V-29847715'\nWHERE \\"USER_ID\\" = 2 AND person_id = 65;\n\n-- 1b. Clean trailing space in last_name from t_user source\nUPDATE t_persons \nSET last_name = TRIM(last_name)\nWHERE person_id = 90;\n\n-- 1c. Log the merge\nINSERT INTO t_person_merge_log (ci, source_table, source_id, field_name, value_used, value_over, overridden_from, severity)\nVALUES \n('V-29847715', 't_user', 2, 'CI_FORMAT', 'V-29847715', '29847715', 't_students', 'INFO'),\n('V-29847715', 't_user', 2, 'PERSON_MERGE', 'person_id=90 (student)', 'person_id=65 (user)', 'auto-merge', 'INFO');\n\n-- 1d. Delete duplicate person\nDELETE FROM t_persons WHERE person_id = 65;\n\n-- 2. NORMALIZE CI format: Add hyphen to CIs WITHOUT conflict\n-- person_id=125 skipped because \\"V-12345678\\" conflicts with existing person_id=66\nUPDATE t_persons \nSET ci = CASE \n    WHEN ci = 'V00000000' THEN 'V-00000000'\n    WHEN ci = 'V23456789' THEN 'V-23456789'\n    WHEN ci = 'V34567890' THEN 'V-34567890'\n    WHEN ci = 'V45678901' THEN 'V-45678901'\n    ELSE ci\nEND\nWHERE person_id IN (124, 126, 127, 128)\nAND ci IN ('V00000000', 'V23456789', 'V34567890', 'V45678901');\n\n-- 3. Log CI normalizations\nINSERT INTO t_person_merge_log (ci, source_table, source_id, field_name, value_used, value_over, overridden_from, severity)\nSELECT ci, 't_persons', person_id, 'CI_FORMAT', ci, \n       CASE \n           WHEN person_id = 124 THEN 'V00000000'\n           WHEN person_id = 126 THEN 'V23456789'\n           WHEN person_id = 127 THEN 'V34567890'\n           WHEN person_id = 128 THEN 'V45678901'\n       END,\n       'auto-normalize', 'INFO'\nFROM t_persons \nWHERE person_id IN (124, 126, 127, 128)\nAND ci IN ('V-00000000', 'V-23456789', 'V-34567890', 'V-45678901');"}	normalize_persons_ci_format_v2	antonysamuel0903@gmail.com	\N	\N
20260525165548	{"-- FASE 9: Dropear columnas legacy de datos personales\n-- Los datos ahora viven exclusivamente en t_persons + person_id FK\n\n-- ============================================================\n-- t_students\n-- ============================================================\nALTER TABLE t_students\n  DROP COLUMN \\"STUDENTS_CI\\" CASCADE,\n  DROP COLUMN \\"NAME\\",\n  DROP COLUMN \\"SECOND_NAME\\",\n  DROP COLUMN \\"SURNAME\\",\n  DROP COLUMN \\"SECOND_SURNAME\\",\n  DROP COLUMN \\"GENDER\\",\n  DROP COLUMN \\"BIRTHDATE\\",\n  DROP COLUMN \\"MARITAL_STATUS\\",\n  DROP COLUMN \\"CONTACT_PHONE\\",\n  DROP COLUMN \\"EMAIL\\",\n  DROP COLUMN \\"ADDRESS\\";\n\n-- ============================================================\n-- t_tutors\n-- ============================================================\nALTER TABLE t_tutors\n  DROP COLUMN \\"TUTOR_CI\\" CASCADE,\n  DROP COLUMN \\"NAME\\",\n  DROP COLUMN \\"SECOND_NAME\\",\n  DROP COLUMN \\"SURNAME\\",\n  DROP COLUMN \\"SECOND_SURNAME\\",\n  DROP COLUMN \\"CONTACT_PHONE\\",\n  DROP COLUMN \\"GENDER\\",\n  DROP COLUMN \\"EMAIL\\";\n\n-- ============================================================\n-- t_user (USER_CI se queda — necesario para login)\n-- ============================================================\nALTER TABLE t_user\n  DROP COLUMN \\"NAME\\",\n  DROP COLUMN \\"SECOND_NAME\\",\n  DROP COLUMN \\"SURNAME\\",\n  DROP COLUMN \\"SECOND_SURNAME\\",\n  DROP COLUMN \\"EMAIL\\",\n  DROP COLUMN \\"PHONE_NUMBER\\";\n\n-- ============================================================\n-- t_institution_manager\n-- ============================================================\nALTER TABLE t_institution_manager\n  DROP COLUMN \\"MANAGER_CI\\" CASCADE,\n  DROP COLUMN \\"NAME\\",\n  DROP COLUMN \\"SECOND_NAME\\",\n  DROP COLUMN \\"SURNAME\\",\n  DROP COLUMN \\"SECOND_SURNAME\\",\n  DROP COLUMN \\"CONTACT_PHONE\\",\n  DROP COLUMN \\"EMAIL\\";"}	drop_legacy_person_columns	antonysamuel0903@gmail.com	\N	\N
20260525170917	{"-- ROLLBACK: Re-agregar columnas legacy (FASE 9 temporal rollback)\n-- Se dropearon antes de tiempo. Se re-agregan para no romper la app.\n-- Los datos de persona ahora viven en t_persons, estas columnas quedan\n-- para compatibilidad con controladores no refactorizados.\n\n-- ============================================================\n-- t_students\n-- ============================================================\nALTER TABLE t_students\n  ADD COLUMN \\"STUDENTS_CI\\" varchar(20),\n  ADD COLUMN \\"NAME\\" varchar(100),\n  ADD COLUMN \\"SECOND_NAME\\" varchar(100),\n  ADD COLUMN \\"SURNAME\\" varchar(100),\n  ADD COLUMN \\"SECOND_SURNAME\\" varchar(100),\n  ADD COLUMN \\"GENDER\\" char(1),\n  ADD COLUMN \\"BIRTHDATE\\" date,\n  ADD COLUMN \\"MARITAL_STATUS\\" varchar(1),\n  ADD COLUMN \\"CONTACT_PHONE\\" varchar(20),\n  ADD COLUMN \\"EMAIL\\" varchar(100),\n  ADD COLUMN \\"ADDRESS\\" text;\n\nCREATE UNIQUE INDEX t_students_STUDENTS_CI_key ON t_students (\\"STUDENTS_CI\\")\n  WHERE \\"STUDENTS_CI\\" IS NOT NULL;\n\n-- ============================================================\n-- t_tutors\n-- ============================================================\nALTER TABLE t_tutors\n  ADD COLUMN \\"TUTOR_CI\\" varchar(20),\n  ADD COLUMN \\"NAME\\" varchar(100),\n  ADD COLUMN \\"SECOND_NAME\\" varchar(100),\n  ADD COLUMN \\"SURNAME\\" varchar(100),\n  ADD COLUMN \\"SECOND_SURNAME\\" varchar(100),\n  ADD COLUMN \\"CONTACT_PHONE\\" varchar(20),\n  ADD COLUMN \\"GENDER\\" char(1),\n  ADD COLUMN \\"EMAIL\\" varchar(100);\n\nCREATE UNIQUE INDEX t_tutors_TUTOR_CI_key ON t_tutors (\\"TUTOR_CI\\")\n  WHERE \\"TUTOR_CI\\" IS NOT NULL;\n\n-- ============================================================\n-- t_institution_manager\n-- ============================================================\nALTER TABLE t_institution_manager\n  ADD COLUMN \\"MANAGER_CI\\" varchar(20),\n  ADD COLUMN \\"NAME\\" varchar(100),\n  ADD COLUMN \\"SECOND_NAME\\" varchar(100),\n  ADD COLUMN \\"SURNAME\\" varchar(100),\n  ADD COLUMN \\"SECOND_SURNAME\\" varchar(100),\n  ADD COLUMN \\"CONTACT_PHONE\\" varchar(20),\n  ADD COLUMN \\"EMAIL\\" varchar(100);\n\nCREATE UNIQUE INDEX t_institution_manager_MANAGER_CI_key ON t_institution_manager (\\"MANAGER_CI\\")\n  WHERE \\"MANAGER_CI\\" IS NOT NULL;\n\n-- ============================================================\n-- t_user\n-- ============================================================\nALTER TABLE t_user\n  ADD COLUMN \\"NAME\\" varchar(100),\n  ADD COLUMN \\"SECOND_NAME\\" varchar(100),\n  ADD COLUMN \\"SURNAME\\" varchar(100),\n  ADD COLUMN \\"SECOND_SURNAME\\" varchar(100),\n  ADD COLUMN \\"EMAIL\\" varchar(100),\n  ADD COLUMN \\"PHONE_NUMBER\\" varchar(20);"}	rollback_legacy_person_columns	antonysamuel0903@gmail.com	\N	\N
20260526184601	{"ALTER TABLE IF EXISTS \\"t_roles\\" ADD COLUMN IF NOT EXISTS \\"IS_SYSTEM\\" BOOLEAN DEFAULT FALSE;"}	add_is_system_to_roles	antonysamuel0903@gmail.com	\N	\N
20260526184608	{"ALTER TABLE IF EXISTS \\"t_user\\" ADD COLUMN IF NOT EXISTS \\"LAST_LOGIN\\" TIMESTAMP;"}	add_last_login_to_user	antonysamuel0903@gmail.com	\N	\N
20260527183142	{"-- Migration 004: Add PERSON_ID foreign keys to remaining entity tables\n-- Normaliza la BD para que todas las tablas que referencian personas\n-- tengan un FK directo a t_persons, eliminando la necesidad de\n-- joins anidados a través de t_students / t_tutors.\n\n-- 1. t_professional_practices → t_persons (vía student)\n-- Tabla central: prácticas profesionales. Cada práctica tiene UN estudiante.\nALTER TABLE \\"t_professional_practices\\" ADD COLUMN IF NOT EXISTS student_person_id INTEGER;\nUPDATE \\"t_professional_practices\\" pp\n  SET student_person_id = s.person_id\n  FROM \\"t_students\\" s\n  WHERE pp.\\"STUDENTS_ID\\" = s.\\"STUDENTS_ID\\";\nALTER TABLE \\"t_professional_practices\\" ALTER COLUMN student_person_id SET NOT NULL;\nALTER TABLE \\"t_professional_practices\\" ADD CONSTRAINT fk_pp_student_person\n  FOREIGN KEY (student_person_id) REFERENCES t_persons(person_id) ON DELETE RESTRICT;\nCREATE INDEX IF NOT EXISTS idx_pp_student_person_id ON \\"t_professional_practices\\"(student_person_id);\n\n-- 2. t_activity_logs → t_persons (vía student)\nALTER TABLE \\"t_activity_logs\\" ADD COLUMN IF NOT EXISTS student_person_id INTEGER;\nUPDATE \\"t_activity_logs\\" al\n  SET student_person_id = s.person_id\n  FROM \\"t_students\\" s\n  WHERE al.\\"STUDENT_ID\\" = s.\\"STUDENTS_ID\\";\nALTER TABLE \\"t_activity_logs\\" ALTER COLUMN student_person_id SET NOT NULL;\nALTER TABLE \\"t_activity_logs\\" ADD CONSTRAINT fk_activity_logs_student_person\n  FOREIGN KEY (student_person_id) REFERENCES t_persons(person_id) ON DELETE RESTRICT;\nCREATE INDEX IF NOT EXISTS idx_activity_logs_student_person_id ON \\"t_activity_logs\\"(student_person_id);\n\n-- 3. t_student_requests → t_persons (vía student)\nALTER TABLE \\"t_student_requests\\" ADD COLUMN IF NOT EXISTS student_person_id INTEGER;\nUPDATE \\"t_student_requests\\" sr\n  SET student_person_id = s.person_id\n  FROM \\"t_students\\" s\n  WHERE sr.\\"STUDENT_ID\\" = s.\\"STUDENTS_ID\\";\nALTER TABLE \\"t_student_requests\\" ALTER COLUMN student_person_id SET NOT NULL;\nALTER TABLE \\"t_student_requests\\" ADD CONSTRAINT fk_student_requests_student_person\n  FOREIGN KEY (student_person_id) REFERENCES t_persons(person_id) ON DELETE RESTRICT;\nCREATE INDEX IF NOT EXISTS idx_student_requests_student_person_id ON \\"t_student_requests\\"(student_person_id);\n\n-- 4. t_student_documents → t_persons (vía student)\nALTER TABLE \\"t_student_documents\\" ADD COLUMN IF NOT EXISTS student_person_id INTEGER;\nUPDATE \\"t_student_documents\\" sd\n  SET student_person_id = s.person_id\n  FROM \\"t_students\\" s\n  WHERE sd.\\"STUDENT_ID\\" = s.\\"STUDENTS_ID\\";\nALTER TABLE \\"t_student_documents\\" ALTER COLUMN student_person_id SET NOT NULL;\nALTER TABLE \\"t_student_documents\\" ADD CONSTRAINT fk_student_documents_student_person\n  FOREIGN KEY (student_person_id) REFERENCES t_persons(person_id) ON DELETE RESTRICT;\nCREATE INDEX IF NOT EXISTS idx_student_documents_student_person_id ON \\"t_student_documents\\"(student_person_id);\n\n-- 5. t_professional_practices_tutor → t_persons (vía tutor)\nALTER TABLE \\"t_professional_practices_tutor\\" ADD COLUMN IF NOT EXISTS tutor_person_id INTEGER;\nUPDATE \\"t_professional_practices_tutor\\" ppt\n  SET tutor_person_id = t.person_id\n  FROM \\"t_tutors\\" t\n  WHERE ppt.\\"TUTOR_ID\\" = t.\\"TUTOR_ID\\";\nALTER TABLE \\"t_professional_practices_tutor\\" ALTER COLUMN tutor_person_id SET NOT NULL;\nALTER TABLE \\"t_professional_practices_tutor\\" ADD CONSTRAINT fk_ppt_tutor_person\n  FOREIGN KEY (tutor_person_id) REFERENCES t_persons(person_id) ON DELETE RESTRICT;\nCREATE INDEX IF NOT EXISTS idx_ppt_tutor_person_id ON \\"t_professional_practices_tutor\\"(tutor_person_id);\n\n-- 6. t_practice_visits → t_persons (vía tutor)\n-- Las visitas siempre tienen un tutor asignado\nALTER TABLE \\"t_practice_visits\\" ADD COLUMN IF NOT EXISTS tutor_person_id INTEGER;\nUPDATE \\"t_practice_visits\\" pv\n  SET tutor_person_id = t.person_id\n  FROM \\"t_tutors\\" t\n  WHERE pv.\\"TUTOR_ID\\" = t.\\"TUTOR_ID\\";\nALTER TABLE \\"t_practice_visits\\" ALTER COLUMN tutor_person_id SET NOT NULL;\nALTER TABLE \\"t_practice_visits\\" ADD CONSTRAINT fk_practice_visits_tutor_person\n  FOREIGN KEY (tutor_person_id) REFERENCES t_persons(person_id) ON DELETE RESTRICT;\nCREATE INDEX IF NOT EXISTS idx_practice_visits_tutor_person_id ON \\"t_practice_visits\\"(tutor_person_id);"}	004_add_remaining_person_fks	antonysamuel0903@gmail.com	\N	\N
20260608210010	{"CREATE OR REPLACE FUNCTION public.trg_set_student_person_id()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n  IF NEW.student_person_id IS NULL AND NEW.\\"STUDENTS_ID\\" IS NOT NULL THEN\n    SELECT person_id INTO NEW.student_person_id\n    FROM \\"t_students\\"\n    WHERE \\"STUDENTS_ID\\" = NEW.\\"STUDENTS_ID\\";\n  END IF;\n  RETURN NEW;\nEND;\n$function$;"}	fix_trg_set_student_person_id_column_name	antonysamuel0903@gmail.com	\N	\N
20260527183352	{"-- Migration 004b: Triggers para auto-setear student_person_id / tutor_person_id\n-- Elimina la necesidad de actualizar CADA INSERT manualmente.\n\n-- 1. Trigger para t_professional_practices: auto-setear student_person_id desde STUDENTS_ID\nCREATE OR REPLACE FUNCTION trg_set_student_person_id()\nRETURNS TRIGGER AS $$\nBEGIN\n  IF NEW.student_person_id IS NULL AND NEW.\\"STUDENTS_ID\\" IS NOT NULL THEN\n    SELECT person_id INTO NEW.student_person_id\n    FROM \\"t_students\\"\n    WHERE \\"STUDENTS_ID\\" = NEW.\\"STUDENTS_ID\\";\n  END IF;\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\nDROP TRIGGER IF EXISTS trg_professional_practices_set_student_person ON \\"t_professional_practices\\";\nCREATE TRIGGER trg_professional_practices_set_student_person\n  BEFORE INSERT ON \\"t_professional_practices\\"\n  FOR EACH ROW\n  EXECUTE FUNCTION trg_set_student_person_id();\n\n-- 2. Trigger para t_activity_logs: auto-setear student_person_id desde STUDENT_ID\nDROP TRIGGER IF EXISTS trg_activity_logs_set_student_person ON \\"t_activity_logs\\";\nCREATE TRIGGER trg_activity_logs_set_student_person\n  BEFORE INSERT ON \\"t_activity_logs\\"\n  FOR EACH ROW\n  EXECUTE FUNCTION trg_set_student_person_id();\n\n-- 3. Trigger para t_student_requests: auto-setear student_person_id desde STUDENT_ID\nDROP TRIGGER IF EXISTS trg_student_requests_set_student_person ON \\"t_student_requests\\";\nCREATE TRIGGER trg_student_requests_set_student_person\n  BEFORE INSERT ON \\"t_student_requests\\"\n  FOR EACH ROW\n  EXECUTE FUNCTION trg_set_student_person_id();\n\n-- 4. Trigger para t_student_documents: auto-setear student_person_id desde STUDENT_ID\nDROP TRIGGER IF EXISTS trg_student_documents_set_student_person ON \\"t_student_documents\\";\nCREATE TRIGGER trg_student_documents_set_student_person\n  BEFORE INSERT ON \\"t_student_documents\\"\n  FOR EACH ROW\n  EXECUTE FUNCTION trg_set_student_person_id();\n\n-- 5. Trigger para t_professional_practices_tutor: auto-setear tutor_person_id desde TUTOR_ID\nCREATE OR REPLACE FUNCTION trg_set_tutor_person_id()\nRETURNS TRIGGER AS $$\nBEGIN\n  IF NEW.tutor_person_id IS NULL AND NEW.\\"TUTOR_ID\\" IS NOT NULL THEN\n    SELECT person_id INTO NEW.tutor_person_id\n    FROM \\"t_tutors\\"\n    WHERE \\"TUTOR_ID\\" = NEW.\\"TUTOR_ID\\";\n  END IF;\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\nDROP TRIGGER IF EXISTS trg_ppt_set_tutor_person ON \\"t_professional_practices_tutor\\";\nCREATE TRIGGER trg_ppt_set_tutor_person\n  BEFORE INSERT ON \\"t_professional_practices_tutor\\"\n  FOR EACH ROW\n  EXECUTE FUNCTION trg_set_tutor_person_id();\n\n-- 6. Trigger para t_practice_visits: auto-setear tutor_person_id desde TUTOR_ID\nDROP TRIGGER IF EXISTS trg_practice_visits_set_tutor_person ON \\"t_practice_visits\\";\nCREATE TRIGGER trg_practice_visits_set_tutor_person\n  BEFORE INSERT ON \\"t_practice_visits\\"\n  FOR EACH ROW\n  EXECUTE FUNCTION trg_set_tutor_person_id();"}	004b_add_person_fk_triggers	antonysamuel0903@gmail.com	\N	\N
20260528143117	{"CREATE OR REPLACE FUNCTION trg_set_student_person_id()\nRETURNS TRIGGER AS $$\nBEGIN\n  IF NEW.student_person_id IS NULL AND NEW.\\"STUDENT_ID\\" IS NOT NULL THEN\n    SELECT person_id INTO NEW.student_person_id\n    FROM \\"t_students\\"\n    WHERE \\"STUDENTS_ID\\" = NEW.\\"STUDENT_ID\\";\n  END IF;\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;"}	fix_student_requests_trigger_column_name	antonysamuel0903@gmail.com	\N	\N
20260529122339	{"-- Migration 005: Add MODULE column and UNIQUE constraint on NAME to t_permissions\nALTER TABLE \\"t_permissions\\" ADD COLUMN IF NOT EXISTS \\"MODULE\\" VARCHAR(30);\nUPDATE \\"t_permissions\\" SET \\"MODULE\\" = 'General' WHERE \\"MODULE\\" IS NULL;\nALTER TABLE \\"t_permissions\\" ALTER COLUMN \\"MODULE\\" SET NOT NULL;\nDELETE FROM \\"t_permissions\\" a USING \\"t_permissions\\" b\nWHERE a.\\"PERMISSIONS_ID\\" < b.\\"PERMISSIONS_ID\\"\n  AND a.\\"NAME\\" = b.\\"NAME\\";\nALTER TABLE \\"t_permissions\\" ADD CONSTRAINT \\"uq_permissions_name\\" UNIQUE (\\"NAME\\");"}	005_add_permissions_module_and_unique_name	antonysamuel0903@gmail.com	\N	\N
20260605184346	{"-- Agrega columna COMITE_MEMBER_INDEX para soportar 3 evaluadores de comité\n-- Actualiza chk_score_range de 1-5 a 1-10\n\nALTER TABLE t_evaluation\n  ADD COLUMN \\"COMITE_MEMBER_INDEX\\" INT DEFAULT NULL;\n\nALTER TABLE t_evaluation\n  ADD CONSTRAINT chk_comite_member_index\n  CHECK (\n    (\\"EVALUATOR_TYPE\\" = 'COMITE' AND \\"COMITE_MEMBER_INDEX\\" BETWEEN 1 AND 3)\n    OR\n    (\\"EVALUATOR_TYPE\\" != 'COMITE' AND \\"COMITE_MEMBER_INDEX\\" IS NULL)\n  );\n\nALTER TABLE t_evaluation_detail\n  DROP CONSTRAINT IF EXISTS chk_score_range;\n\nALTER TABLE t_evaluation_detail\n  ADD CONSTRAINT chk_score_range\n  CHECK (\\"SCORE\\" >= 1 AND \\"SCORE\\" <= 10);"}	comite_member_index	antonysamuel0903@gmail.com	\N	\N
20260605191506	{"CREATE TABLE IF NOT EXISTS \\"t_prospect_lists\\" (\n  \\"LIST_ID\\" SERIAL NOT NULL,\n  \\"NAME\\" VARCHAR(255) NOT NULL,\n  \\"DESCRIPTION\\" TEXT,\n  \\"PERIOD_ID\\" INTEGER NOT NULL,\n  \\"STATUS\\" SMALLINT NOT NULL DEFAULT 1,\n  \\"CREATED_AT\\" TIMESTAMP NOT NULL DEFAULT NOW(),\n  \\"UPDATED_AT\\" TIMESTAMP NOT NULL DEFAULT NOW(),\n  \\"CREATED_BY\\" INTEGER,\n  PRIMARY KEY (\\"LIST_ID\\")\n);\n\nALTER TABLE \\"t_prospect_lists\\"\n  ADD CONSTRAINT \\"fk_prospect_lists_period\\"\n  FOREIGN KEY (\\"PERIOD_ID\\") REFERENCES \\"t_internships_period\\" (\\"PERIOD_ID\\");\n\nALTER TABLE \\"t_prospect_lists\\"\n  ADD CONSTRAINT \\"fk_prospect_lists_user\\"\n  FOREIGN KEY (\\"CREATED_BY\\") REFERENCES \\"t_user\\" (\\"USER_ID\\");\n\nCREATE TABLE IF NOT EXISTS \\"t_prospect_list_items\\" (\n  \\"ITEM_ID\\" SERIAL NOT NULL,\n  \\"LIST_ID\\" INTEGER NOT NULL,\n  \\"STUDENTS_ID\\" INTEGER NOT NULL,\n  \\"ENROLLED\\" BOOLEAN NOT NULL DEFAULT FALSE,\n  \\"NOTES\\" TEXT,\n  \\"ADDED_AT\\" TIMESTAMP NOT NULL DEFAULT NOW(),\n  \\"ADDED_BY\\" INTEGER,\n  PRIMARY KEY (\\"ITEM_ID\\")\n);\n\nALTER TABLE \\"t_prospect_list_items\\"\n  ADD CONSTRAINT \\"fk_prospect_items_list\\"\n  FOREIGN KEY (\\"LIST_ID\\") REFERENCES \\"t_prospect_lists\\" (\\"LIST_ID\\") ON DELETE CASCADE;\n\nALTER TABLE \\"t_prospect_list_items\\"\n  ADD CONSTRAINT \\"fk_prospect_items_student\\"\n  FOREIGN KEY (\\"STUDENTS_ID\\") REFERENCES \\"t_students\\" (\\"STUDENTS_ID\\");\n\nALTER TABLE \\"t_prospect_list_items\\"\n  ADD CONSTRAINT \\"fk_prospect_items_user\\"\n  FOREIGN KEY (\\"ADDED_BY\\") REFERENCES \\"t_user\\" (\\"USER_ID\\");\n\nALTER TABLE \\"t_prospect_list_items\\"\n  ADD CONSTRAINT \\"uq_prospect_list_student\\"\n  UNIQUE (\\"LIST_ID\\", \\"STUDENTS_ID\\");"}	007_prospect_lists	antonysamuel0903@gmail.com	\N	\N
20260607190203	{"-- Migration: 009_email_templates\n-- Crea la tabla de plantillas de email editables para el correo express\n-- y siembra las 4 plantillas iniciales.\n\nCREATE TABLE IF NOT EXISTS \\"t_email_templates\\" (\n  \\"id\\" SERIAL PRIMARY KEY,\n  \\"name\\" VARCHAR(255) NOT NULL,\n  \\"description\\" TEXT,\n  \\"category\\" VARCHAR(50) NOT NULL DEFAULT 'general',\n  \\"subject\\" VARCHAR(500) NOT NULL,\n  \\"body_html\\" TEXT NOT NULL,\n  \\"created_at\\" TIMESTAMPTZ DEFAULT NOW(),\n  \\"updated_at\\" TIMESTAMPTZ DEFAULT NOW()\n);\n\nCOMMENT ON TABLE \\"t_email_templates\\" IS 'Plantillas de email editables para correo express';\nCOMMENT ON COLUMN \\"t_email_templates\\".\\"category\\" IS 'Categoría: periodo, evaluacion, general';\n\nINSERT INTO \\"t_email_templates\\" (\\"name\\", \\"description\\", \\"category\\", \\"subject\\", \\"body_html\\")\nSELECT * FROM (VALUES\n(\n  'Inicio de Lapso Académico',\n  'Notificar a estudiantes sobre el inicio de un nuevo período académico',\n  'periodo',\n  '📢 Inicio de lapso {{periodo}}',\n  '<div style=\\"font-family: sans-serif; max-width: 600px; margin: 0 auto;\\">\n    <div style=\\"background: #1e40af; padding: 20px; text-align: center; color: white;\\">\n      <h1 style=\\"margin: 0;\\">SIGP UNEFA</h1>\n    </div>\n    <div style=\\"padding: 24px; color: #1e293b;\\">\n      <h2>¡Bienvenido al {{periodo}}, {{nombre}}!</h2>\n      <p>Informamos que el lapso académico <strong>{{periodo}}</strong> ha dado inicio el día <strong>{{fecha_inicio}}</strong>.</p>\n      <p>Te recordamos mantener tus datos al día y revisar las actividades programadas para este período.</p>\n      <hr style=\\"border-top: 1px solid #e2e8f0;\\">\n      <p style=\\"font-size: 12px; color: #94a3b8; text-align: center;\\">SIGP UNEFA — Sistema de Gestión de Personal</p>\n    </div>\n  </div>'\n),\n(\n  'Fin de Lapso Académico',\n  'Notificar a estudiantes sobre el cierre del período académico',\n  'periodo',\n  '⏰ Cierre de lapso {{periodo}}',\n  '<div style=\\"font-family: sans-serif; max-width: 600px; margin: 0 auto;\\">\n    <div style=\\"background: #1e40af; padding: 20px; text-align: center; color: white;\\">\n      <h1 style=\\"margin: 0;\\">SIGP UNEFA</h1>\n    </div>\n    <div style=\\"padding: 24px; color: #1e293b;\\">\n      <h2>Cierre del {{periodo}}</h2>\n      <p>Hola {{nombre}},</p>\n      <p>Te informamos que el lapso académico <strong>{{periodo}}</strong> finaliza el <strong>{{fecha_fin}}</strong>.</p>\n      <p>Asegurate de tener toda tu documentación al día antes del cierre.</p>\n      <hr style=\\"border-top: 1px solid #e2e8f0;\\">\n      <p style=\\"font-size: 12px; color: #94a3b8; text-align: center;\\">SIGP UNEFA — Sistema de Gestión de Personal</p>\n    </div>\n  </div>'\n),\n(\n  'Reporte de Evaluación',\n  'Notificar a tutores sobre reportes de evaluación disponibles',\n  'evaluacion',\n  '📋 Reporte de evaluación disponible',\n  '<div style=\\"font-family: sans-serif; max-width: 600px; margin: 0 auto;\\">\n    <div style=\\"background: #1e40af; padding: 20px; text-align: center; color: white;\\">\n      <h1 style=\\"margin: 0;\\">SIGP UNEFA</h1>\n    </div>\n    <div style=\\"padding: 24px; color: #1e293b;\\">\n      <h2>Reporte de Evaluación</h2>\n      <p>Hola {{nombre}},</p>\n      <p>Tenés disponible el reporte de evaluación del período <strong>{{periodo}}</strong>.</p>\n      <p>Ingresá al sistema para revisar los resultados y completar las evaluaciones pendientes de tus estudiantes asignados.</p>\n      <hr style=\\"border-top: 1px solid #e2e8f0;\\">\n      <p style=\\"font-size: 12px; color: #94a3b8; text-align: center;\\">SIGP UNEFA — Sistema de Gestión de Personal</p>\n    </div>\n  </div>'\n),\n(\n  'Aviso General',\n  'Plantilla genérica para comunicados institucionales',\n  'general',\n  '{{asunto}}',\n  '<div style=\\"font-family: sans-serif; max-width: 600px; margin: 0 auto;\\">\n    <div style=\\"background: #1e40af; padding: 20px; text-align: center; color: white;\\">\n      <h1 style=\\"margin: 0;\\">SIGP UNEFA</h1>\n    </div>\n    <div style=\\"padding: 24px; color: #1e293b;\\">\n      <h2>{{asunto}}</h2>\n      <p>Hola {{nombre}},</p>\n      <p>{{mensaje}}</p>\n      <hr style=\\"border-top: 1px solid #e2e8f0;\\">\n      <p style=\\"font-size: 12px; color: #94a3b8; text-align: center;\\">SIGP UNEFA — Sistema de Gestión de Personal</p>\n    </div>\n  </div>')\n) AS v\nWHERE NOT EXISTS (SELECT 1 FROM \\"t_email_templates\\" LIMIT 1);"}	009_email_templates	antonysamuel0903@gmail.com	\N	\N
20260608004343	{"-- Migration 010: Knowledge Base para chat Groq\n-- Crea tabla t_knowledge_base con soporte pgvector para RAG semántico\n\n-- Habilitar extension vector si no existe\nCREATE EXTENSION IF NOT EXISTS vector;\n\n-- Tabla principal de conocimiento\nCREATE TABLE IF NOT EXISTS t_knowledge_base (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    title TEXT NOT NULL,\n    category TEXT NOT NULL CHECK (category IN ('regulation', 'curriculum', 'process', 'faq', 'general')),\n    content TEXT NOT NULL,\n    embedding vector(768),\n    metadata JSONB DEFAULT '{}'::jsonb,\n    roles INTEGER[] DEFAULT NULL,\n    is_active BOOLEAN DEFAULT true,\n    created_at TIMESTAMPTZ DEFAULT NOW(),\n    updated_at TIMESTAMPTZ DEFAULT NOW()\n);\n\n-- Índices\nCREATE INDEX IF NOT EXISTS idx_kb_category ON t_knowledge_base(category);\nCREATE INDEX IF NOT EXISTS idx_kb_active ON t_knowledge_base(is_active);\n\n-- Índice IVFFlat para búsqueda por similitud coseno\n-- lists=100 es apropiado para < 100K entries\nCREATE INDEX IF NOT EXISTS idx_kb_embedding ON t_knowledge_base\n    USING ivfflat (embedding vector_cosine_ops) WITH (lists = 100);\n\n-- Trigger para actualizar updated_at automáticamente\nCREATE OR REPLACE FUNCTION update_kb_updated_at()\nRETURNS TRIGGER AS $$\nBEGIN\n    NEW.updated_at = NOW();\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\nDROP TRIGGER IF EXISTS trg_kb_updated_at ON t_knowledge_base;\nCREATE TRIGGER trg_kb_updated_at\n    BEFORE UPDATE ON t_knowledge_base\n    FOR EACH ROW\n    EXECUTE FUNCTION update_kb_updated_at();\n\n-- RPC function para búsqueda semántica por similitud coseno\nCREATE OR REPLACE FUNCTION search_knowledge_base(\n    query_embedding vector(768),\n    match_threshold double precision DEFAULT 0.7,\n    match_limit integer DEFAULT 5,\n    filter_category text DEFAULT NULL,\n    filter_roles integer[] DEFAULT NULL\n)\nRETURNS TABLE(\n    id UUID,\n    title TEXT,\n    category TEXT,\n    content TEXT,\n    metadata JSONB,\n    similarity double precision\n)\nLANGUAGE plpgsql\nAS $$\nBEGIN\n    RETURN QUERY\n    SELECT\n        kb.id,\n        kb.title,\n        kb.category,\n        kb.content,\n        kb.metadata,\n        1 - (kb.embedding <=> query_embedding) AS similarity\n    FROM t_knowledge_base kb\n    WHERE kb.is_active = true\n      AND (filter_category IS NULL OR kb.category = filter_category)\n      AND (filter_roles IS NULL OR kb.roles IS NULL OR kb.roles && filter_roles)\n      AND 1 - (kb.embedding <=> query_embedding) >= match_threshold\n    ORDER BY kb.embedding <=> query_embedding\n    LIMIT match_limit;\nEND;\n$$;"}	010_knowledge_base	antonysamuel0903@gmail.com	\N	\N
