20260613023339	{"-- ============================================================================\n-- Migration: V006__address_system\n-- Description: Normalize address system — add offline-sync columns, constraints,\n--              cascade behavior, and migrate existing flat address data\n--              into the normalized schema.\n--\n-- Safe to run multiple times (all operations use IF NOT EXISTS / idempotent guards).\n-- Old VARCHAR columns on t_persons and t_institution remain untouched.\n-- ============================================================================\n\n-- Make parroquia_id nullable first (needed for data migration)\nALTER TABLE \\"t_address\\" ALTER COLUMN \\"parroquia_id\\" DROP NOT NULL;\n\n-- ============================================================================\n-- Phase 1: Schema — Add Columns (all IF NOT EXISTS)\n-- ============================================================================\n\n-- t_address: add uuid, full_address, updated_at, version, deleted_at\nALTER TABLE \\"t_address\\" ADD COLUMN IF NOT EXISTS \\"uuid\\" UUID DEFAULT gen_random_uuid();\nALTER TABLE \\"t_address\\" ADD COLUMN IF NOT EXISTS \\"full_address\\" VARCHAR(500);\nALTER TABLE \\"t_address\\" ADD COLUMN IF NOT EXISTS \\"updated_at\\" TIMESTAMPTZ DEFAULT NOW();\nALTER TABLE \\"t_address\\" ADD COLUMN IF NOT EXISTS \\"version\\" INTEGER DEFAULT 1;\nALTER TABLE \\"t_address\\" ADD COLUMN IF NOT EXISTS \\"deleted_at\\" TIMESTAMPTZ;\n\n-- t_person_address: add uuid, updated_at, version\nALTER TABLE \\"t_person_address\\" ADD COLUMN IF NOT EXISTS \\"uuid\\" UUID DEFAULT gen_random_uuid();\nALTER TABLE \\"t_person_address\\" ADD COLUMN IF NOT EXISTS \\"updated_at\\" TIMESTAMPTZ DEFAULT NOW();\nALTER TABLE \\"t_person_address\\" ADD COLUMN IF NOT EXISTS \\"version\\" INTEGER DEFAULT 1;\n\n-- t_institution_address: add uuid, updated_at, version, is_primary (for consistency)\nALTER TABLE \\"t_institution_address\\" ADD COLUMN IF NOT EXISTS \\"uuid\\" UUID DEFAULT gen_random_uuid();\nALTER TABLE \\"t_institution_address\\" ADD COLUMN IF NOT EXISTS \\"updated_at\\" TIMESTAMPTZ DEFAULT NOW();\nALTER TABLE \\"t_institution_address\\" ADD COLUMN IF NOT EXISTS \\"version\\" INTEGER DEFAULT 1;\nALTER TABLE \\"t_institution_address\\" ADD COLUMN IF NOT EXISTS \\"is_primary\\" BOOLEAN DEFAULT FALSE;\n\n-- ============================================================================\n-- Phase 2: Constraints (safe — DO blocks with pg_constraint introspection)\n-- ============================================================================\n\n-- Make uuid NOT NULL (safe because all existing rows get a default via Phase 1)\nALTER TABLE \\"t_address\\" ALTER COLUMN \\"uuid\\" SET NOT NULL;\nALTER TABLE \\"t_person_address\\" ALTER COLUMN \\"uuid\\" SET NOT NULL;\nALTER TABLE \\"t_institution_address\\" ALTER COLUMN \\"uuid\\" SET NOT NULL;\n\n-- Unique constraint on t_address.uuid\nDO $$\nBEGIN\n  IF NOT EXISTS (\n    SELECT 1 FROM pg_catalog.pg_constraint\n    WHERE conname = 'uq_address_uuid' AND conrelid = 't_address'::regclass\n  ) THEN\n    ALTER TABLE \\"t_address\\" ADD CONSTRAINT \\"uq_address_uuid\\" UNIQUE (\\"uuid\\");\n  END IF;\nEND $$;\n\n-- Unique composite constraint on t_person_address\nDO $$\nBEGIN\n  IF NOT EXISTS (\n    SELECT 1 FROM pg_catalog.pg_constraint\n    WHERE conname = 'uq_person_address' AND conrelid = 't_person_address'::regclass\n  ) THEN\n    ALTER TABLE \\"t_person_address\\" ADD CONSTRAINT \\"uq_person_address\\" UNIQUE (\\"person_id\\", \\"address_id\\", \\"address_type_id\\");\n  END IF;\nEND $$;\n\n-- Unique composite constraint on t_institution_address\nDO $$\nBEGIN\n  IF NOT EXISTS (\n    SELECT 1 FROM pg_catalog.pg_constraint\n    WHERE conname = 'uq_institution_address' AND conrelid = 't_institution_address'::regclass\n  ) THEN\n    ALTER TABLE \\"t_institution_address\\" ADD CONSTRAINT \\"uq_institution_address\\" UNIQUE (\\"institution_id\\", \\"address_id\\", \\"address_type_id\\");\n  END IF;\nEND $$;\n\n-- ============================================================================\n-- Phase 3: ON DELETE CASCADE on Entity FKs\n-- ============================================================================\n\n-- t_person_address.person_id → t_persons.person_id (CASCADE)\nDO $$\nDECLARE\n  v_fk_name TEXT;\n  v_exists  BOOLEAN;\nBEGIN\n  SELECT EXISTS (\n    SELECT 1 FROM pg_catalog.pg_constraint con\n    JOIN pg_catalog.pg_class rel ON rel.oid = con.conrelid\n    JOIN pg_catalog.pg_class rel2 ON rel2.oid = con.confrelid\n    WHERE rel.relname = 't_person_address'\n      AND rel2.relname = 't_persons'\n      AND con.contype = 'f'\n      AND con.confdeltype = 'c'\n  ) INTO v_exists;\n\n  IF NOT v_exists THEN\n    SELECT con.conname INTO v_fk_name\n    FROM pg_catalog.pg_constraint con\n    JOIN pg_catalog.pg_class rel ON rel.oid = con.conrelid\n    JOIN pg_catalog.pg_class rel2 ON rel2.oid = con.confrelid\n    WHERE rel.relname = 't_person_address'\n      AND rel2.relname = 't_persons'\n      AND con.contype = 'f';\n\n    IF v_fk_name IS NOT NULL THEN\n      EXECUTE format('ALTER TABLE \\"t_person_address\\" DROP CONSTRAINT %I', v_fk_name);\n    END IF;\n\n    EXECUTE 'ALTER TABLE \\"t_person_address\\" ADD CONSTRAINT \\"fk_person_address_person\\" FOREIGN KEY (\\"person_id\\") REFERENCES \\"t_persons\\" (\\"person_id\\") ON DELETE CASCADE';\n  END IF;\nEND $$;\n\n-- t_institution_address.institution_id → t_institution.INSTITUTION_ID (CASCADE)\nDO $$\nDECLARE\n  v_fk_name TEXT;\n  v_exists  BOOLEAN;\nBEGIN\n  SELECT EXISTS (\n    SELECT 1 FROM pg_catalog.pg_constraint con\n    JOIN pg_catalog.pg_class rel ON rel.oid = con.conrelid\n    JOIN pg_catalog.pg_class rel2 ON rel2.oid = con.confrelid\n    WHERE rel.relname = 't_institution_address'\n      AND rel2.relname = 't_institution'\n      AND con.contype = 'f'\n      AND con.confdeltype = 'c'\n  ) INTO v_exists;\n\n  IF NOT v_exists THEN\n    SELECT con.conname INTO v_fk_name\n    FROM pg_catalog.pg_constraint con\n    JOIN pg_catalog.pg_class rel ON rel.oid = con.conrelid\n    JOIN pg_catalog.pg_class rel2 ON rel2.oid = con.confrelid\n    WHERE rel.relname = 't_institution_address'\n      AND rel2.relname = 't_institution'\n      AND con.contype = 'f';\n\n    IF v_fk_name IS NOT NULL THEN\n      EXECUTE format('ALTER TABLE \\"t_institution_address\\" DROP CONSTRAINT %I', v_fk_name);\n    END IF;\n\n    EXECUTE 'ALTER TABLE \\"t_institution_address\\" ADD CONSTRAINT \\"fk_institution_address_institution\\" FOREIGN KEY (\\"institution_id\\") REFERENCES \\"t_institution\\" (\\"INSTITUTION_ID\\") ON DELETE CASCADE';\n  END IF;\nEND $$;\n\n-- ============================================================================\n-- Phase 4: Data Migration (idempotent — skips if bridge tables already populated)\n-- ============================================================================\n\nDO $$\nDECLARE\n  v_person_count BIGINT;\n  v_institution_count BIGINT;\n  v_addr_id BIGINT;\n  v_person RECORD;\n  v_institution RECORD;\nBEGIN\n  -- Idempotency guard: only run if no bridge links exist yet\n  SELECT COUNT(*) INTO v_person_count FROM \\"t_person_address\\";\n  SELECT COUNT(*) INTO v_institution_count FROM \\"t_institution_address\\";\n\n  IF v_person_count > 0 OR v_institution_count > 0 THEN\n    RAISE NOTICE 'Bridge tables already populated, skipping data migration (t_person_address: %, t_institution_address: %)', v_person_count, v_institution_count;\n    RETURN;\n  END IF;\n\n  RAISE NOTICE 'Starting data migration for addresses...';\n\n  -- ─── Migrate t_persons.address into t_address + t_person_address ───\n  -- Use cursor to avoid cross-product JOIN on duplicate address text\n  FOR v_person IN\n    SELECT \\"person_id\\", \\"address\\" FROM \\"t_persons\\"\n    WHERE \\"address\\" IS NOT NULL AND \\"address\\" != ''\n  LOOP\n    INSERT INTO \\"t_address\\" (\\"parroquia_id\\", \\"street_address\\", \\"full_address\\", \\"updated_at\\", \\"version\\")\n    VALUES (NULL, v_person.\\"address\\", v_person.\\"address\\", NOW(), 1)\n    RETURNING \\"address_id\\" INTO v_addr_id;\n\n    INSERT INTO \\"t_person_address\\" (\\"person_id\\", \\"address_id\\", \\"address_type_id\\", \\"is_primary\\", \\"updated_at\\", \\"version\\")\n    VALUES (v_person.\\"person_id\\", v_addr_id, 2, TRUE, NOW(), 1)\n    ON CONFLICT (\\"person_id\\", \\"address_id\\", \\"address_type_id\\") DO NOTHING;\n  END LOOP;\n\n  -- ─── Migrate t_institution.INSTITUTION_ADDRESS into t_address + t_institution_address ───\n  FOR v_institution IN\n    SELECT \\"INSTITUTION_ID\\", \\"INSTITUTION_ADDRESS\\" FROM \\"t_institution\\"\n    WHERE \\"INSTITUTION_ADDRESS\\" IS NOT NULL AND \\"INSTITUTION_ADDRESS\\" != ''\n  LOOP\n    INSERT INTO \\"t_address\\" (\\"parroquia_id\\", \\"street_address\\", \\"full_address\\", \\"updated_at\\", \\"version\\")\n    VALUES (NULL, v_institution.\\"INSTITUTION_ADDRESS\\", v_institution.\\"INSTITUTION_ADDRESS\\", NOW(), 1)\n    RETURNING \\"address_id\\" INTO v_addr_id;\n\n    INSERT INTO \\"t_institution_address\\" (\\"institution_id\\", \\"address_id\\", \\"address_type_id\\", \\"is_primary\\", \\"updated_at\\", \\"version\\")\n    VALUES (v_institution.\\"INSTITUTION_ID\\", v_addr_id, 1, TRUE, NOW(), 1)\n    ON CONFLICT (\\"institution_id\\", \\"address_id\\", \\"address_type_id\\") DO NOTHING;\n  END LOOP;\n\n  RAISE NOTICE 'Data migration complete.';\nEND $$;\n\n-- ============================================================================\n-- Phase 5: Fill full_address for existing rows that still have NULL full_address\n-- ============================================================================\n\nUPDATE \\"t_address\\"\nSET \\"full_address\\" = CASE\n  WHEN \\"reference\\" IS NOT NULL AND \\"reference\\" != '' THEN \\"street_address\\" || ' — ' || \\"reference\\"\n  ELSE \\"street_address\\"\nEND\nWHERE \\"full_address\\" IS NULL;"}	V006__address_system	antonysamuel0903@gmail.com	\N	\N
20260614001411	{"-- Migration: 014_text_normalization\n-- Description: Normalize existing text data to UPPERCASE for consistency.\n-- Part of the text-normalization change (SDD).\n-- All new data will be sanitized by the backend sanitizeText() utility.\n-- This migration is idempotent — running it multiple times is safe.\n\nBEGIN;\n\n-- ============================================================\n-- t_persons\n-- ============================================================\nUPDATE \\"t_persons\\" SET\n  \\"first_name\\" = UPPER(TRIM(\\"first_name\\")),\n  \\"middle_name\\" = UPPER(TRIM(\\"middle_name\\")),\n  \\"last_name\\" = UPPER(TRIM(\\"last_name\\")),\n  \\"second_last_name\\" = UPPER(TRIM(\\"second_last_name\\")),\n  \\"address\\" = UPPER(TRIM(\\"address\\")),\n  \\"gender\\" = UPPER(TRIM(\\"gender\\")),\n  \\"marital_status\\" = UPPER(TRIM(\\"marital_status\\"))\nWHERE\n  \\"first_name\\" IS DISTINCT FROM UPPER(TRIM(\\"first_name\\")) OR\n  \\"middle_name\\" IS DISTINCT FROM UPPER(TRIM(\\"middle_name\\")) OR\n  \\"last_name\\" IS DISTINCT FROM UPPER(TRIM(\\"last_name\\")) OR\n  \\"second_last_name\\" IS DISTINCT FROM UPPER(TRIM(\\"second_last_name\\")) OR\n  \\"address\\" IS DISTINCT FROM UPPER(TRIM(\\"address\\")) OR\n  \\"gender\\" IS DISTINCT FROM UPPER(TRIM(\\"gender\\")) OR\n  \\"marital_status\\" IS DISTINCT FROM UPPER(TRIM(\\"marital_status\\"));\n\n-- ============================================================\n-- t_institution\n-- ============================================================\nUPDATE \\"t_institution\\" SET\n  \\"INSTITUTION_NAME\\" = UPPER(TRIM(\\"INSTITUTION_NAME\\")),\n  \\"INSTITUTION_ADDRESS\\" = UPPER(TRIM(\\"INSTITUTION_ADDRESS\\")),\n  \\"INSTITUTION_CONTACT\\" = UPPER(TRIM(\\"INSTITUTION_CONTACT\\")),\n  \\"REGION\\" = UPPER(TRIM(\\"REGION\\")),\n  \\"NUCLEUS\\" = UPPER(TRIM(\\"NUCLEUS\\")),\n  \\"EXTENSION\\" = UPPER(TRIM(\\"EXTENSION\\")),\n  \\"INSTITUTION_TYPE\\" = UPPER(TRIM(\\"INSTITUTION_TYPE\\")),\n  \\"RIF\\" = UPPER(TRIM(\\"RIF\\"))\nWHERE\n  \\"INSTITUTION_NAME\\" IS DISTINCT FROM UPPER(TRIM(\\"INSTITUTION_NAME\\")) OR\n  \\"INSTITUTION_ADDRESS\\" IS DISTINCT FROM UPPER(TRIM(\\"INSTITUTION_ADDRESS\\")) OR\n  \\"INSTITUTION_CONTACT\\" IS DISTINCT FROM UPPER(TRIM(\\"INSTITUTION_CONTACT\\")) OR\n  \\"REGION\\" IS DISTINCT FROM UPPER(TRIM(\\"REGION\\")) OR\n  \\"NUCLEUS\\" IS DISTINCT FROM UPPER(TRIM(\\"NUCLEUS\\")) OR\n  \\"EXTENSION\\" IS DISTINCT FROM UPPER(TRIM(\\"EXTENSION\\")) OR\n  \\"INSTITUTION_TYPE\\" IS DISTINCT FROM UPPER(TRIM(\\"INSTITUTION_TYPE\\")) OR\n  \\"RIF\\" IS DISTINCT FROM UPPER(TRIM(\\"RIF\\"));\n\n-- ============================================================\n-- t_students\n-- ============================================================\nUPDATE \\"t_students\\" SET\n  \\"STUDENT_TYPE\\" = UPPER(TRIM(\\"STUDENT_TYPE\\")),\n  \\"MILITARY_RANK\\" = UPPER(TRIM(\\"MILITARY_RANK\\")),\n  \\"EMPLOYMENT\\" = UPPER(TRIM(\\"EMPLOYMENT\\"))\nWHERE\n  \\"STUDENT_TYPE\\" IS DISTINCT FROM UPPER(TRIM(\\"STUDENT_TYPE\\")) OR\n  \\"MILITARY_RANK\\" IS DISTINCT FROM UPPER(TRIM(\\"MILITARY_RANK\\")) OR\n  \\"EMPLOYMENT\\" IS DISTINCT FROM UPPER(TRIM(\\"EMPLOYMENT\\"));\n\n-- ============================================================\n-- t_tutors\n-- ============================================================\nUPDATE \\"t_tutors\\" SET\n  \\"PROFESSION\\" = UPPER(TRIM(\\"PROFESSION\\")),\n  \\"CONDITION\\" = UPPER(TRIM(\\"CONDITION\\")),\n  \\"DEDICATION\\" = UPPER(TRIM(\\"DEDICATION\\")),\n  \\"CATEGORY\\" = UPPER(TRIM(\\"CATEGORY\\")),\n  \\"TITULO\\" = UPPER(TRIM(\\"TITULO\\"))\nWHERE\n  \\"PROFESSION\\" IS DISTINCT FROM UPPER(TRIM(\\"PROFESSION\\")) OR\n  \\"CONDITION\\" IS DISTINCT FROM UPPER(TRIM(\\"CONDITION\\")) OR\n  \\"DEDICATION\\" IS DISTINCT FROM UPPER(TRIM(\\"DEDICATION\\")) OR\n  \\"CATEGORY\\" IS DISTINCT FROM UPPER(TRIM(\\"CATEGORY\\")) OR\n  \\"TITULO\\" IS DISTINCT FROM UPPER(TRIM(\\"TITULO\\"));\n\n-- ============================================================\n-- t_career\n-- ============================================================\nUPDATE \\"t_career\\" SET\n  \\"CAREER_NAME\\" = UPPER(TRIM(\\"CAREER_NAME\\")),\n  \\"CAREER_CODE\\" = UPPER(TRIM(\\"CAREER_CODE\\")),\n  \\"CAREER_ABBREVIATION\\" = UPPER(TRIM(\\"CAREER_ABBREVIATION\\")),\n  \\"CAREER_TYPE\\" = UPPER(TRIM(\\"CAREER_TYPE\\"))\nWHERE\n  \\"CAREER_NAME\\" IS DISTINCT FROM UPPER(TRIM(\\"CAREER_NAME\\")) OR\n  \\"CAREER_CODE\\" IS DISTINCT FROM UPPER(TRIM(\\"CAREER_CODE\\")) OR\n  \\"CAREER_ABBREVIATION\\" IS DISTINCT FROM UPPER(TRIM(\\"CAREER_ABBREVIATION\\")) OR\n  \\"CAREER_TYPE\\" IS DISTINCT FROM UPPER(TRIM(\\"CAREER_TYPE\\"));\n\n-- ============================================================\n-- t_user\n-- ============================================================\nUPDATE \\"t_user\\" SET\n  \\"NAME\\" = UPPER(TRIM(\\"NAME\\")),\n  \\"SECOND_NAME\\" = UPPER(TRIM(\\"SECOND_NAME\\")),\n  \\"SURNAME\\" = UPPER(TRIM(\\"SURNAME\\")),\n  \\"SECOND_SURNAME\\" = UPPER(TRIM(\\"SECOND_SURNAME\\"))\nWHERE\n  \\"NAME\\" IS DISTINCT FROM UPPER(TRIM(\\"NAME\\")) OR\n  \\"SECOND_NAME\\" IS DISTINCT FROM UPPER(TRIM(\\"SECOND_NAME\\")) OR\n  \\"SURNAME\\" IS DISTINCT FROM UPPER(TRIM(\\"SURNAME\\")) OR\n  \\"SECOND_SURNAME\\" IS DISTINCT FROM UPPER(TRIM(\\"SECOND_SURNAME\\"));\n\n-- Note: EMAIL intentionally NOT normalized — emails preserve original casing\n\n-- ============================================================\n-- t_professional_practices\n-- ============================================================\nUPDATE \\"t_professional_practices\\" SET\n  \\"REPORT_TITLE\\" = UPPER(TRIM(\\"REPORT_TITLE\\")),\n  \\"OBSERVATION\\" = UPPER(TRIM(\\"OBSERVATION\\")),\n  \\"ENROLLMENT\\" = UPPER(TRIM(\\"ENROLLMENT\\")),\n  \\"SEMESTER\\" = UPPER(TRIM(\\"SEMESTER\\")),\n  \\"SECTION\\" = UPPER(TRIM(\\"SECTION\\")),\n  \\"REGIME\\" = UPPER(TRIM(\\"REGIME\\")),\n  \\"TOUR\\" = UPPER(TRIM(\\"TOUR\\"))\nWHERE\n  \\"REPORT_TITLE\\" IS DISTINCT FROM UPPER(TRIM(\\"REPORT_TITLE\\")) OR\n  \\"OBSERVATION\\" IS DISTINCT FROM UPPER(TRIM(\\"OBSERVATION\\")) OR\n  \\"ENROLLMENT\\" IS DISTINCT FROM UPPER(TRIM(\\"ENROLLMENT\\")) OR\n  \\"SEMESTER\\" IS DISTINCT FROM UPPER(TRIM(\\"SEMESTER\\")) OR\n  \\"SECTION\\" IS DISTINCT FROM UPPER(TRIM(\\"SECTION\\")) OR\n  \\"REGIME\\" IS DISTINCT FROM UPPER(TRIM(\\"REGIME\\")) OR\n  \\"TOUR\\" IS DISTINCT FROM UPPER(TRIM(\\"TOUR\\"));\n\n-- ============================================================\n-- t_value_list\n-- ============================================================\nUPDATE \\"t_value_list\\" SET\n  \\"NAME\\" = UPPER(TRIM(\\"NAME\\")),\n  \\"ABBREVIATION\\" = UPPER(TRIM(\\"ABBREVIATION\\"))\nWHERE\n  \\"NAME\\" IS DISTINCT FROM UPPER(TRIM(\\"NAME\\")) OR\n  \\"ABBREVIATION\\" IS DISTINCT FROM UPPER(TRIM(\\"ABBREVIATION\\"));\n\n-- ============================================================\n-- t_internship_type\n-- ============================================================\nUPDATE \\"t_internship_type\\" SET\n  \\"NAME\\" = UPPER(TRIM(\\"NAME\\"))\nWHERE\n  \\"NAME\\" IS DISTINCT FROM UPPER(TRIM(\\"NAME\\"));\n\n-- ============================================================\n-- t_internships_period\n-- ============================================================\nUPDATE \\"t_internships_period\\" SET\n  \\"DESCRIPTION\\" = UPPER(TRIM(\\"DESCRIPTION\\"))\nWHERE\n  \\"DESCRIPTION\\" IS DISTINCT FROM UPPER(TRIM(\\"DESCRIPTION\\"));\n\n-- ============================================================\n-- t_roles\n-- ============================================================\nUPDATE \\"t_roles\\" SET\n  \\"NAME\\" = UPPER(TRIM(\\"NAME\\"))\nWHERE\n  \\"NAME\\" IS DISTINCT FROM UPPER(TRIM(\\"NAME\\"));\n\n-- ============================================================\n-- t_institution_manager\n-- ============================================================\nUPDATE \\"t_institution_manager\\" SET\n  \\"NAME\\" = UPPER(TRIM(\\"NAME\\")),\n  \\"SECOND_NAME\\" = UPPER(TRIM(\\"SECOND_NAME\\")),\n  \\"SURNAME\\" = UPPER(TRIM(\\"SURNAME\\")),\n  \\"SECOND_SURNAME\\" = UPPER(TRIM(\\"SECOND_SURNAME\\")),\n  \\"TITLE\\" = UPPER(TRIM(\\"TITLE\\"))\nWHERE\n  \\"NAME\\" IS DISTINCT FROM UPPER(TRIM(\\"NAME\\")) OR\n  \\"SECOND_NAME\\" IS DISTINCT FROM UPPER(TRIM(\\"SECOND_NAME\\")) OR\n  \\"SURNAME\\" IS DISTINCT FROM UPPER(TRIM(\\"SURNAME\\")) OR\n  \\"SECOND_SURNAME\\" IS DISTINCT FROM UPPER(TRIM(\\"SECOND_SURNAME\\")) OR\n  \\"TITLE\\" IS DISTINCT FROM UPPER(TRIM(\\"TITLE\\"));\n\n-- ============================================================\n-- t_practice_visits\n-- ============================================================\nUPDATE \\"t_practice_visits\\" SET\n  \\"VISIT_TYPE\\" = UPPER(TRIM(\\"VISIT_TYPE\\")),\n  \\"VISIT_CASE\\" = UPPER(TRIM(\\"VISIT_CASE\\")),\n  \\"ACTIVITIES_PERFORMED\\" = UPPER(TRIM(\\"ACTIVITIES_PERFORMED\\")),\n  \\"OBSERVATIONS\\" = UPPER(TRIM(\\"OBSERVATIONS\\")),\n  \\"RECOMMENDATIONS\\" = UPPER(TRIM(\\"RECOMMENDATIONS\\"))\nWHERE\n  \\"VISIT_TYPE\\" IS DISTINCT FROM UPPER(TRIM(\\"VISIT_TYPE\\")) OR\n  \\"VISIT_CASE\\" IS DISTINCT FROM UPPER(TRIM(\\"VISIT_CASE\\")) OR\n  \\"ACTIVITIES_PERFORMED\\" IS DISTINCT FROM UPPER(TRIM(\\"ACTIVITIES_PERFORMED\\")) OR\n  \\"OBSERVATIONS\\" IS DISTINCT FROM UPPER(TRIM(\\"OBSERVATIONS\\")) OR\n  \\"RECOMMENDATIONS\\" IS DISTINCT FROM UPPER(TRIM(\\"RECOMMENDATIONS\\"));\n\n-- ============================================================\n-- t_activity_logs (only type, NOT description — long text)\n-- ============================================================\nUPDATE \\"t_activity_logs\\" SET\n  \\"ACTIVITY_TYPE\\" = UPPER(TRIM(\\"ACTIVITY_TYPE\\"))\nWHERE\n  \\"ACTIVITY_TYPE\\" IS DISTINCT FROM UPPER(TRIM(\\"ACTIVITY_TYPE\\"));\n\n-- ============================================================\n-- t_notifications\n-- ============================================================\nUPDATE \\"t_notifications\\" SET\n  \\"TITLE\\" = UPPER(TRIM(\\"TITLE\\")),\n  \\"MESSAGE\\" = UPPER(TRIM(\\"MESSAGE\\"))\nWHERE\n  \\"TITLE\\" IS DISTINCT FROM UPPER(TRIM(\\"TITLE\\")) OR\n  \\"MESSAGE\\" IS DISTINCT FROM UPPER(TRIM(\\"MESSAGE\\"));\n\n-- ============================================================\n-- t_student_requests\n-- ============================================================\nUPDATE \\"t_student_requests\\" SET\n  \\"SUBJECT\\" = UPPER(TRIM(\\"SUBJECT\\"))\nWHERE\n  \\"SUBJECT\\" IS DISTINCT FROM UPPER(TRIM(\\"SUBJECT\\"));\n-- Note: DESCRIPTION and RESPONSE are long TEXT fields — intentionally NOT normalized\n\n-- ============================================================\n-- t_student_documents\n-- ============================================================\nUPDATE \\"t_student_documents\\" SET\n  \\"TITLE\\" = UPPER(TRIM(\\"TITLE\\")),\n  \\"DOCUMENT_TYPE\\" = UPPER(TRIM(\\"DOCUMENT_TYPE\\")),\n  \\"STATUS\\" = UPPER(TRIM(\\"STATUS\\"))\nWHERE\n  \\"TITLE\\" IS DISTINCT FROM UPPER(TRIM(\\"TITLE\\")) OR\n  \\"DOCUMENT_TYPE\\" IS DISTINCT FROM UPPER(TRIM(\\"DOCUMENT_TYPE\\")) OR\n  \\"STATUS\\" IS DISTINCT FROM UPPER(TRIM(\\"STATUS\\"));\n-- Note: DESCRIPTION and REJECTION_REASON are long TEXT — intentionally NOT normalized\n\nCOMMIT;"}	014_text_normalization	antonysamuel0903@gmail.com	\N	\N
